Page({
  data: {
    nickname: '',
    avatarInitial: '心',
    storageMode: 'local',
    storageModeText: '仅本地存储',
    dailyReminder: false
  },

  onShow() {
    const nickname = wx.getStorageSync('nickname') || '';
    const storageMode = wx.getStorageSync('storageMode') || 'local';
    const initial = nickname ? nickname[0] : '心';
    const storageModeText =
      storageMode === 'encrypted' ? '加密云端存储（预留）' : '仅本地存储';
    this.setData({
      nickname,
      storageMode,
      storageModeText,
      avatarInitial: initial
    });
  },

  changeStorageMode() {
    const that = this;
    wx.showActionSheet({
      itemList: ['仅本地存储', '加密云端存储（预留）'],
      success(res) {
        const index = res.tapIndex;
        const mode = index === 1 ? 'encrypted' : 'local';
        const text =
          mode === 'encrypted' ? '加密云端存储（预留）' : '仅本地存储';
        that.setData({ storageMode: mode, storageModeText: text });
        wx.setStorageSync('storageMode', mode);
      }
    });
  },

  exportData() {
    wx.showToast({
      title: '导出功能待后续版本支持',
      icon: 'none'
    });
  },

  clearAllData() {
    wx.showModal({
      title: '确认清空所有数据？',
      content: '这会删除你的全部情绪记录和设置，且无法恢复，请谨慎操作。',
      confirmText: '仍要清空',
      confirmColor: '#E27A7A',
      success(res) {
        if (res.confirm) {
          wx.clearStorageSync();
          wx.showToast({
            title: '已清空',
            icon: 'success'
          });
        }
      }
    });
  },

  toggleDailyReminder(e) {
    const value = e.detail.value;
    this.setData({
      dailyReminder: value
    });
    wx.showToast({
      title: '提醒功能为占位示例',
      icon: 'none'
    });
  }
})
