const MOOD_TEXT = {
  1: '状态不太好，可以先照顾好自己。',
  2: '有点低落，试着慢慢放松一下。',
  3: '一般般，今天也算平稳的一天。',
  4: '整体还不错，可以好好享受当下。',
  5: '感觉很好，把这份感觉记下来吧！'
};

Page({
  data: {
    displayTime: '',
    moodLevel: 3,
    moodLabel: MOOD_TEXT[3],
    moodTags: [
      { label: '焦虑', value: '焦虑', active: false },
      { label: '疲惫', value: '疲惫', active: false },
      { label: '开心', value: '开心', active: false },
      { label: '平静', value: '平静', active: false },
      { label: '失落', value: '失落', active: false },
      { label: '生气', value: '生气', active: false },
      { label: '紧张', value: '紧张', active: false },
      { label: '期待', value: '期待', active: false }
    ],
    triggerTags: [
      { label: '学业', value: '学业', active: false },
      { label: '工作', value: '工作', active: false },
      { label: '人际关系', value: '人际关系', active: false },
      { label: '家庭', value: '家庭', active: false },
      { label: '睡眠', value: '睡眠', active: false },
      { label: '身体状态', value: '身体状态', active: false },
      { label: '金钱', value: '金钱', active: false },
      { label: '其他', value: '其他', active: false }
    ],
    content: '',
    isRecording: false,
    recordDuration: 0,
    aiPreview: null
  },

  onShow() {
    this._refreshTime();
  },

  onPullDownRefresh() {
    this._resetForm();
    wx.stopPullDownRefresh();
  },

  _refreshTime() {
    const now = new Date();
    const h = now.getHours().toString().padStart(2, '0');
    const m = now.getMinutes().toString().padStart(2, '0');
    this.setData({
      displayTime: `${h}:${m}`
    });
  },

  onMoodChange(e) {
    const value = Number(e.detail.value || 3);
    this.setData({
      moodLevel: value,
      moodLabel: MOOD_TEXT[value] || MOOD_TEXT[3]
    });
  },

  toggleMoodTag(e) {
    const value = e.currentTarget.dataset.value;
    const moodTags = this.data.moodTags.map(item => ({
      ...item,
      active: item.value === value ? !item.active : item.active
    }));
    this.setData({ moodTags });
  },

  toggleTriggerTag(e) {
    const value = e.currentTarget.dataset.value;
    const triggerTags = this.data.triggerTags.map(item => ({
      ...item,
      active: item.value === value ? !item.active : item.active
    }));
    this.setData({ triggerTags });
  },

  onContentInput(e) {
    this.setData({
      content: e.detail.value
    });
  },

  startRecord() {
    if (this.data.isRecording) return;
    this.setData({
      isRecording: true,
      recordDuration: 0
    });

    const mgr = wx.getRecorderManager();
    this._recordStartTime = Date.now();
    mgr.start({
      duration: 600000,
      sampleRate: 16000,
      encodeBitRate: 96000,
      format: 'mp3'
    });

    mgr.onStop(res => {
      const durationSec = Math.round((Date.now() - this._recordStartTime) / 1000);
      this.setData({
        recordDuration: durationSec > 0 ? durationSec : 0,
        isRecording: false
      });
      // 这里可以把录音文件路径保存到记录中（res.tempFilePath）
    });
  },

  stopRecord() {
    if (!this.data.isRecording) return;
    const mgr = wx.getRecorderManager();
    mgr.stop();
  },

  saveWithoutAnalysis() {
    this._saveRecord({ withAnalysis: false });
  },

  saveWithAnalysis() {
    this._saveRecord({ withAnalysis: true });
  },

  _saveRecord({ withAnalysis }) {
    const now = new Date();
    const dateKey = this._formatDateKey(now);
    const time = this.data.displayTime;
    const selectedMoods = this.data.moodTags.filter(i => i.active).map(i => i.label);
    const selectedTriggers = this.data.triggerTags.filter(i => i.active).map(i => i.label);

    if (!this.data.content && !selectedMoods.length) {
      wx.showToast({
        title: '可以先简单写一句话～',
        icon: 'none'
      });
      return;
    }

    let aiPreview = null;
    if (withAnalysis) {
      aiPreview = this._mockAnalysis({
        moodLevel: this.data.moodLevel,
        moods: selectedMoods,
        triggers: selectedTriggers,
        content: this.data.content
      });
      this.setData({ aiPreview });
    }

    const record = {
      id: Date.now(),
      dateKey,
      time,
      moodLevel: this.data.moodLevel,
      moodLabel: this.data.moodLabel,
      moods: selectedMoods,
      triggers: selectedTriggers,
      content: this.data.content,
      recordDuration: this.data.recordDuration,
      mainEmotion: aiPreview ? aiPreview.mainEmotion : (selectedMoods[0] || ''),
      analysis: aiPreview || null
    };

    const list = wx.getStorageSync('emotionRecords') || [];
    list.push(record);
    wx.setStorageSync('emotionRecords', list);

    wx.showToast({
      title: '已保存',
      icon: 'success'
    });

    setTimeout(() => {
      wx.switchTab({
        url: '/pages/home/home'
      });
    }, 600);
  },

  _mockAnalysis({ moodLevel, moods, triggers, content }) {
    let mainEmotion = '有点复杂';
    if (moods.length) {
      mainEmotion = moods[0];
    } else if (moodLevel <= 2) {
      mainEmotion = '偏低落';
    } else if (moodLevel >= 4) {
      mainEmotion = '整体不错';
    }

    let triggerText = '暂时没有明显的触发事件';
    if (triggers.length) {
      triggerText = triggers.join(' / ');
    }

    let suggestion = '谢谢你愿意把这些写下来，这本身就是在照顾自己。';
    if (mainEmotion.includes('开心') || mainEmotion.includes('期待')) {
      suggestion = '可以记录下让你开心的小片段，以后心情不好时可以翻回来看看。';
    } else if (mainEmotion.includes('焦虑') || mainEmotion.includes('紧张')) {
      suggestion = '试着做 3 分钟深呼吸或短暂走动一下，让身体知道可以慢慢放松。';
    } else if (mainEmotion.includes('疲惫') || content.includes('累')) {
      suggestion = '也许可以给自己多一点休息时间，不需要总是那么用力。';
    }

    return {
      mainEmotion,
      triggers: triggerText,
      suggestion
    };
  },

  _formatDateKey(date) {
    const y = date.getFullYear();
    const m = (date.getMonth() + 1).toString().padStart(2, '0');
    const d = date.getDate().toString().padStart(2, '0');
    return `${y}-${m}-${d}`;
  },

  _resetForm() {
    this.setData({
      moodLevel: 3,
      moodLabel: MOOD_TEXT[3],
      moodTags: this.data.moodTags.map(i => ({ ...i, active: false })),
      triggerTags: this.data.triggerTags.map(i => ({ ...i, active: false })),
      content: '',
      isRecording: false,
      recordDuration: 0,
      aiPreview: null
    });
    this._refreshTime();
  }
})
